-- LOTUS CLINIC initial schema
-- Hand-authored to exactly match prisma/schema.prisma.
--
-- Why this migration is hand-written instead of generated by `prisma migrate dev`:
-- this project was built in a sandboxed environment with no outbound access to a
-- MySQL server and no package-registry access, so the Prisma CLI could not be run
-- against a live database to auto-generate this file. The SQL below was authored to
-- mirror schema.prisma field-for-field. Before you rely on it, run:
--   npx prisma validate   (checks the schema file parses correctly)
--   npx prisma migrate diff --from-empty --to-schema-datamodel prisma/schema.prisma \
--       --script --from-empty > /tmp/check.sql   (compare against this file)
-- and reconcile any differences, then `npx prisma migrate deploy` to apply.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------------
CREATE TABLE `users` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `username` VARCHAR(80) NULL,
  `email` VARCHAR(190) NULL,
  `phone` VARCHAR(40) NULL,
  `passwordHash` VARCHAR(255) NOT NULL,
  `role` ENUM('patient','doctor','chief') NOT NULL,
  `active` BOOLEAN NOT NULL DEFAULT true,
  `mustChangePassword` BOOLEAN NOT NULL DEFAULT false,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL,
  `lastLoginAt` DATETIME(3) NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `users_username_key` (`username`),
  UNIQUE INDEX `users_email_key` (`email`),
  UNIQUE INDEX `users_phone_key` (`phone`),
  INDEX `users_role_idx` (`role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- departments
-- ---------------------------------------------------------------------------
CREATE TABLE `departments` (
  `id` VARCHAR(40) NOT NULL,
  `name` VARCHAR(190) NOT NULL,
  `tag` VARCHAR(80) NULL,
  `icon` VARCHAR(20) NULL,
  `wait` VARCHAR(40) NULL,
  `hours` VARCHAR(190) NULL,
  `desc` TEXT NULL,
  `servicesTags` JSON NULL,
  `symptoms` JSON NULL,
  `equipment` TEXT NULL,
  `checkups` JSON NULL,
  `active` BOOLEAN NOT NULL DEFAULT true,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- patients
-- ---------------------------------------------------------------------------
CREATE TABLE `patients` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `userId` BIGINT NOT NULL,
  `firstName` VARCHAR(120) NOT NULL,
  `lastName` VARCHAR(120) NULL,
  `phone` VARCHAR(40) NOT NULL,
  `email` VARCHAR(190) NULL,
  `dob` DATE NULL,
  `consentAt` DATETIME(3) NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `patients_userId_key` (`userId`),
  INDEX `patients_phone_idx` (`phone`),
  CONSTRAINT `patients_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- doctors
-- ---------------------------------------------------------------------------
CREATE TABLE `doctors` (
  `id` VARCHAR(40) NOT NULL,
  `userId` BIGINT NULL,
  `departmentId` VARCHAR(40) NOT NULL,
  `name` VARCHAR(190) NOT NULL,
  `title` VARCHAR(190) NULL,
  `exp` INT NULL,
  `rating` DECIMAL(2,1) NULL,
  `reviewsCount` INT NOT NULL DEFAULT 0,
  `langs` JSON NULL,
  `price` VARCHAR(40) NULL,
  `ageGroup` VARCHAR(190) NULL,
  `bio` TEXT NULL,
  `initials` VARCHAR(10) NULL,
  `badge` VARCHAR(190) NULL,
  `gender` VARCHAR(5) NULL,
  `mobile` VARCHAR(40) NULL,
  `idNum` VARCHAR(40) NULL,
  `dob` DATE NULL,
  `address` TEXT NULL,
  `specialRole` VARCHAR(190) NULL,
  `specialNote` TEXT NULL,
  `education` JSON NULL,
  `reviewsList` JSON NULL,
  `active` BOOLEAN NOT NULL DEFAULT true,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `doctors_userId_key` (`userId`),
  INDEX `doctors_departmentId_idx` (`departmentId`),
  CONSTRAINT `doctors_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `doctors_departmentId_fkey` FOREIGN KEY (`departmentId`) REFERENCES `departments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- doctor_schedule_templates
-- ---------------------------------------------------------------------------
CREATE TABLE `doctor_schedule_templates` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `doctorId` VARCHAR(40) NOT NULL,
  `weekday` INT NOT NULL,
  `startTime` VARCHAR(5) NOT NULL,
  `slotMinutes` INT NOT NULL DEFAULT 30,
  `slotsPerDay` INT NOT NULL DEFAULT 1,
  `active` BOOLEAN NOT NULL DEFAULT true,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  INDEX `doctor_schedule_templates_doctorId_weekday_idx` (`doctorId`, `weekday`),
  CONSTRAINT `doctor_schedule_templates_doctorId_fkey` FOREIGN KEY (`doctorId`) REFERENCES `doctors`(`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- doctor_availability_overrides
-- ---------------------------------------------------------------------------
CREATE TABLE `doctor_availability_overrides` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `doctorId` VARCHAR(40) NOT NULL,
  `date` DATE NOT NULL,
  `type` VARCHAR(20) NOT NULL,
  `startTime` VARCHAR(5) NULL,
  `reason` VARCHAR(255) NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  INDEX `doctor_availability_overrides_doctorId_date_idx` (`doctorId`, `date`),
  CONSTRAINT `doctor_availability_overrides_doctorId_fkey` FOREIGN KEY (`doctorId`) REFERENCES `doctors`(`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- appointment_slots  (double-booking protection lives on this unique index)
-- ---------------------------------------------------------------------------
CREATE TABLE `appointment_slots` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `doctorId` VARCHAR(40) NOT NULL,
  `slotAt` DATETIME(3) NOT NULL,
  `status` ENUM('open','booked','blocked') NOT NULL DEFAULT 'open',
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE INDEX `appointment_slots_doctorId_slotAt_key` (`doctorId`, `slotAt`),
  INDEX `appointment_slots_doctorId_status_slotAt_idx` (`doctorId`, `status`, `slotAt`),
  CONSTRAINT `appointment_slots_doctorId_fkey` FOREIGN KEY (`doctorId`) REFERENCES `doctors`(`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- appointments
-- ---------------------------------------------------------------------------
CREATE TABLE `appointments` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `patientId` BIGINT NOT NULL,
  `doctorId` VARCHAR(40) NOT NULL,
  `slotId` BIGINT NOT NULL,
  `scheduledAt` DATETIME(3) NOT NULL,
  `status` ENUM('pending','confirmed','completed','cancelled','no_show') NOT NULL DEFAULT 'pending',
  `reason` VARCHAR(255) NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL,
  `cancelledAt` DATETIME(3) NULL,
  `cancelReason` VARCHAR(255) NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `appointments_slotId_key` (`slotId`),
  INDEX `appointments_doctorId_scheduledAt_idx` (`doctorId`, `scheduledAt`),
  INDEX `appointments_patientId_scheduledAt_idx` (`patientId`, `scheduledAt`),
  CONSTRAINT `appointments_patientId_fkey` FOREIGN KEY (`patientId`) REFERENCES `patients`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `appointments_doctorId_fkey` FOREIGN KEY (`doctorId`) REFERENCES `doctors`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `appointments_slotId_fkey` FOREIGN KEY (`slotId`) REFERENCES `appointment_slots`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- consultations
-- ---------------------------------------------------------------------------
CREATE TABLE `consultations` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `appointmentId` BIGINT NOT NULL,
  `doctorId` VARCHAR(40) NOT NULL,
  `patientId` BIGINT NOT NULL,
  `anamnesis` TEXT NULL,
  `icd10Code` VARCHAR(10) NULL,
  `icd10Name` VARCHAR(255) NULL,
  `treatmentNote` TEXT NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `consultations_appointmentId_key` (`appointmentId`),
  INDEX `consultations_patientId_idx` (`patientId`),
  INDEX `consultations_doctorId_idx` (`doctorId`),
  CONSTRAINT `consultations_appointmentId_fkey` FOREIGN KEY (`appointmentId`) REFERENCES `appointments`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `consultations_doctorId_fkey` FOREIGN KEY (`doctorId`) REFERENCES `doctors`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `consultations_patientId_fkey` FOREIGN KEY (`patientId`) REFERENCES `patients`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- medical_records
-- ---------------------------------------------------------------------------
CREATE TABLE `medical_records` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `patientId` BIGINT NOT NULL,
  `bloodType` VARCHAR(10) NULL,
  `allergies` TEXT NULL,
  `chronicConditions` TEXT NULL,
  `updatedByUserId` BIGINT NULL,
  `updatedAt` DATETIME(3) NOT NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE INDEX `medical_records_patientId_key` (`patientId`),
  CONSTRAINT `medical_records_patientId_fkey` FOREIGN KEY (`patientId`) REFERENCES `patients`(`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- services
-- ---------------------------------------------------------------------------
CREATE TABLE `services` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `departmentId` VARCHAR(40) NULL,
  `name` VARCHAR(190) NOT NULL,
  `priceLabel` VARCHAR(80) NULL,
  `priceAmount` DECIMAL(10,2) NULL,
  `active` BOOLEAN NOT NULL DEFAULT true,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  INDEX `services_departmentId_idx` (`departmentId`),
  CONSTRAINT `services_departmentId_fkey` FOREIGN KEY (`departmentId`) REFERENCES `departments`(`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------------
-- audit_logs
-- ---------------------------------------------------------------------------
CREATE TABLE `audit_logs` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `userId` BIGINT NULL,
  `action` VARCHAR(100) NOT NULL,
  `targetType` VARCHAR(60) NULL,
  `targetId` VARCHAR(60) NULL,
  `meta` JSON NULL,
  `ip` VARCHAR(64) NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  INDEX `audit_logs_userId_idx` (`userId`),
  INDEX `audit_logs_action_idx` (`action`),
  CONSTRAINT `audit_logs_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS = 1;
